<script setup lang="ts">
import {ref,computed,onMounted} from 'vue'
import {api,user,refreshAuth,message,notify,date,type Work} from '../api'
import WorkCard from '../components/WorkCard.vue'
import Icon from '../components/Icon.vue'
import ProfileForm from '../components/ProfileForm.vue'
const works=ref<Work[]>([]),bookmarks=ref<Work[]>([]),tab=ref('全部稿件'),error=ref(''),pen=ref(user.value?.penName||''),bio=ref(user.value?.bio||'')
const filtered=computed(()=>works.value.filter(w=>tab.value==='草稿箱'?w.status!=='PUBLISHED':tab.value==='已发布'?w.status==='PUBLISHED':true))
async function load(){try{const [w,b]=await Promise.all([api.get('/member/works'),api.get('/member/bookmarks')]);works.value=w.data;bookmarks.value=b.data}catch(e){error.value=message(e)}}
async function withdraw(id:number){if(!confirm('撤回后作品将不再公开展示，可以再次编辑发布。确认撤回？'))return;try{await api.post(`/member/works/${id}/withdraw`);await load();notify('作品已撤回')}catch(e){notify(message(e))}}
async function profile(){try{await api.put('/member/profile',{penName:pen.value,bio:bio.value});await refreshAuth();notify('个人资料已更新')}catch(e){notify(message(e))}}
onMounted(load)
</script>
<template><div class="container page-space"><div class="desk-heading"><div><p class="eyebrow">MY WRITING DESK</p><h1 class="page-title">{{user?.penName}}的书桌</h1><p class="page-description">管理稿件、合集与收藏。</p></div><RouterLink to="/write" class="button"><Icon name="Plus"/>新建作品</RouterLink></div><div class="desk-collection-links"><RouterLink to="/profile" class="text-button">个人中心 →</RouterLink><RouterLink to="/collection-edit" class="text-button">＋ 新建合集</RouterLink><RouterLink to="/collections?mine=1" class="text-button">我的合集 →</RouterLink></div><div class="desk-stats"><div><strong>{{works.length}}</strong><span>全部稿件</span></div><div><strong>{{works.filter(w=>w.status==='PUBLISHED').length}}</strong><span>已发布</span></div><div><strong>{{bookmarks.length}}</strong><span>收藏的作品</span></div></div><div class="genre-tabs desk-tabs"><button v-for="t in ['全部稿件','草稿箱','已发布','我的收藏','个人资料']" :key="t" :class="{selected:tab===t}" @click="tab=t">{{t}}</button></div><p v-if="error" class="error-message">{{error}}</p><section v-if="tab==='个人资料'" class="panel profile-form"><h2>个人资料</h2><ProfileForm :key="user?.id"/></section><template v-else-if="tab==='我的收藏'"><div class="works-grid"><WorkCard v-for="(w,i) in bookmarks" :key="w.id" :work="w" :index="i"/></div><div v-if="!bookmarks.length" class="empty-state">暂无收藏</div></template><template v-else><div class="manuscript-list"><article v-for="w in filtered" :key="w.id"><div class="manuscript-icon"><Icon name="FileText" :size="24"/></div><div class="manuscript-main"><RouterLink :to="w.status==='PUBLISHED'?`/work/${w.id}`:`/write/${w.id}`">{{w.title||'未命名草稿'}}</RouterLink><p>{{w.genre}} · {{w.wordCount}} 字 · {{date(w.updatedAt)}} 更新 <span v-if="w.isDemo">· 示例作品</span></p></div><span class="status-badge" :class="{published:w.status==='PUBLISHED'}">{{w.status==='PUBLISHED'?'已发布':w.status==='DRAFT'?'草稿':'已撤回'}}</span><div class="row-actions"><RouterLink :to="`/write/${w.id}`">编辑</RouterLink><button v-if="w.status==='PUBLISHED'" @click="withdraw(w.id)">撤回</button></div></article></div><div v-if="!filtered.length" class="empty-state"><Icon name="Feather" :size="30"/><h3>暂无稿件</h3><RouterLink to="/write" class="text-button">新建作品 →</RouterLink></div></template></div></template>
